using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class CPVerify{
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static Vector3 V(JToken t)=>new Vector3((float)t[0],(float)t[1],(float)t[2]);
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty)throw new Exception("Saved edit scene required");var h=R+"/SourceAssets/CoolingPumpRepair";var data=JObject.Parse(File.ReadAllText(h+"/before.json"));var all=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var errors=new List<string>();var rows=new List<object>();int colliders=0;var unique=new HashSet<Mesh>();
 foreach(var row in data["rows"]){var root=all.Single(x=>x.name==(string)row["name"]);if(Vector3.Distance(root.position,V(row["position"]))>.0001f||Vector3.Distance(root.localPosition,V(row["localPosition"]))>.0001f||Vector3.Distance(root.localScale,V(row["localScale"]))>.0001f||Quaternion.Angle(root.localRotation,Quaternion.Euler(V(row["localEuler"])))>.001f)errors.Add(root.name+" placement changed");foreach(var c in row["colliders"]){GlobalObjectId.TryParse((string)c["id"],out var id);var obj=GlobalObjectId.GlobalObjectIdentifierToObjectSlow(id);if(!obj||EditorJsonUtility.ToJson(obj)!=(string)c["json"])errors.Add(root.name+" collider changed");colliders++;}
 if((string)row["model"]!="BM_CoolingPump")continue;var newR=root.GetComponentsInChildren<MeshRenderer>().Where(r=>r.name.StartsWith("Aligned_LOD")).OrderBy(x=>x.name).ToArray();if(newR.Length==0)continue;
 GlobalObjectId.TryParse((string)row["renderers"][0]["id"],out var sourceId);var source=(MeshRenderer)GlobalObjectId.GlobalObjectIdentifierToObjectSlow(sourceId);var targetMatrix=source.transform.parent.localToWorldMatrix*Matrix4x4.TRS(source.transform.localPosition,Quaternion.identity,source.transform.localScale);var pts=source.GetComponent<MeshFilter>().sharedMesh.vertices.Select(v=>targetMatrix.MultiplyPoint3x4(v)).ToArray();var expected=new Bounds(pts[0],Vector3.zero);foreach(var p in pts)expected.Encapsulate(p);var b=newR[0].bounds;float drift=Mathf.Max(Vector3.Distance(b.min,expected.min),Vector3.Distance(b.max,expected.max));if(Mathf.Abs(b.min.y-root.position.y)>.001f)errors.Add(root.name+" ground mismatch");if(Quaternion.Angle(newR[0].transform.rotation,newR[1].transform.rotation)>.001f)errors.Add(root.name+" LOD tilt mismatch");if(drift>.002f)errors.Add(root.name+" bounds drift: "+drift);
 foreach(var old in row["renderers"]){GlobalObjectId.TryParse((string)old["id"],out var id);var rr=(MeshRenderer)GlobalObjectId.GlobalObjectIdentifierToObjectSlow(id);if(!rr||rr.enabled||AssetDatabase.GetAssetPath(rr.GetComponent<MeshFilter>().sharedMesh)!=(string)old["asset"])errors.Add(root.name+" source preservation failed");}
 var groups=root.GetComponentsInChildren<LODGroup>(true);foreach(var nr in newR){var mesh=nr.GetComponent<MeshFilter>().sharedMesh;unique.Add(mesh);if(!nr.enabled||!nr.sharedMaterials.Any()||nr.sharedMaterials.Any(x=>!x)||mesh.vertexCount==0||mesh.triangles.Length==0)errors.Add(root.name+" invalid renderer");if(groups.Count(g=>g.GetLODs().Any(l=>l.renderers.Contains(nr)))!=1)errors.Add(root.name+" LOD membership invalid");}
 rows.Add(new{name=root.name,lods=newR.Length,boundsDriftMetres=drift,groundY=b.min.y,oldGroundY=(float)row["min"][1],lodTiltDegrees=Quaternion.Angle(newR[0].transform.rotation,newR[1].transform.rotation)});
 }
 var meshes=unique.Select(m=>{var vertices=m.vertices;if(vertices.Any(v=>float.IsNaN(v.x)||float.IsNaN(v.y)||float.IsNaN(v.z)))errors.Add(m.name+" nonfinite");if(m.isReadable)errors.Add(m.name+" CPU copy retained");return new{name=m.name,vertices=m.vertexCount,triangles=m.triangles.Length/3,readable=m.isReadable,bytes=UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(m)};}).ToArray();
 var result=new{scene=s.path,placementsChecked=data["rows"].Count(),collidersChecked=colliders,repairedPlacements=rows,meshes,errors};File.WriteAllText(h+"/validation.json",JsonConvert.SerializeObject(result,Formatting.Indented));return new{placements=data["rows"].Count(),colliders,repaired=rows.Count,meshes=meshes.Length,errors};}
}
